.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #000000;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #FDBB2D;
  --vt-line: #d8d8d8;
  --vt-font-body: 'Fira Sans', sans-serif;
  --vt-font-head: 'Fira Sans Condensed', sans-serif;
  font-family: var(--vt-font-body);
  background: var(--vt-surface);
  color: var(--vt-ink);
  min-height: 100vh;
  margin: 0;
  line-height: 1.6;
}

.root,
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  font-family: var(--vt-font-head);
  color: var(--vt-ink);
  margin: 0;
}

.root :where(button) {
  font: inherit;
  border: 0;
}

.root :where(ul) {
  padding: 0;
  margin: 0;
  list-style: none;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 300px;
  background: var(--vt-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 40px 24px;
  overflow-y: auto;
}

.sidebarInner {
  text-align: center;
  width: 100%;
}

.logo {
  display: inline-block;
  margin-bottom: 70px;
}

.brand {
  font-size: 28px;
  font-family: var(--vt-font-head);
}

.navList {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.navLink {
  display: block;
  padding: 10px 18px;
  font-family: var(--vt-font-head);
  font-size: 18px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--vt-on-accent);
  border-radius: 100px;
  transition: color 0.3s, background-color 0.3s;
}

.navLink:hover {
  color: var(--vt-on-deep);
  background: var(--vt-accent-ink);
}

.content {
  margin-left: 300px;
}

.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 100vh;
  padding: 80px 64px;
  background-color: var(--vt-accent-on-deep);
  background-size: cover;
  background-position: center;
  overflow: hidden;
  border-bottom: 10px solid var(--vt-accent);
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, var(--vt-accent-on-deep) 0%, var(--vt-accent-ink) 130%);
  opacity: 0.65;
}

.heroInner {
  position: relative;
  z-index: 2;
  max-width: 760px;
}

.heroTitle {
  font-size: clamp(44px, 7vw, 84px);
  font-weight: 700;
  line-height: 1.05;
  text-transform: uppercase;
  color: var(--vt-on-deep);
}

.heroTitle em {
  font-style: italic;
  color: var(--vt-accent-on-deep);
}

.heroTag {
  font-size: 22px;
  color: var(--vt-on-deep);
  margin: 24px 0 32px;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.buttonOutline,
.buttonSolid {
  display: inline-block;
  padding: 13px 26px;
  border-radius: 100px;
  font-family: var(--vt-font-head);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: background-color 0.3s, color 0.3s, border-color 0.3s;
}

.buttonOutline {
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
}

.buttonOutline:hover {
  background: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.buttonSolid {
  background: var(--vt-accent-ink);
  border: 2px solid var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

.buttonSolid:hover {
  background: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
  color: var(--vt-surface-deep);
}

.section {
  padding: 100px 64px;
}

.container {
  max-width: 1180px;
  margin: 0 auto;
}

.section h2,
.contactTop h2 {
  font-size: 46px;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  margin-bottom: 32px;
}

.storyLayout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.storyText p {
  font-size: 20px;
  color: var(--vt-ink-soft);
  line-height: 1.7;
  margin: 0 0 16px;
  max-width: 720px;
}

.storyImageWrap {
  position: relative;
}

.storyImage {
  width: 100%;
  height: 380px;
  object-fit: cover;
  border-radius: 20px;
  transform: rotate(2deg);
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

